--   Detail: Failing row contains (null, 2021-09-24 15:52:59.169, 1969-12-31 18:00:00, t, 2021-09-24 15:52:59.169, null, f, Manages site configurations and settings for the XNAT system., siteConfig, XNAT Site Preferences).
-- If that can be figured out and fixed, then these should be removed.
CREATE TABLE IF NOT EXISTS xhbm_tool (id BIGSERIAL PRIMARY KEY, created TIMESTAMP NOT NULL, disabled TIMESTAMP NOT NULL, enabled BOOLEAN DEFAULT TRUE, timestamp TIMESTAMP NOT NULL, resolver VARCHAR(255), strict BOOLEAN NOT NULL, tool_description VARCHAR(255), tool_id VARCHAR(255) NOT NULL UNIQUE, tool_name VARCHAR(255) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS xhbm_preference (id BIGSERIAL PRIMARY KEY, created TIMESTAMP NOT NULL, disabled TIMESTAMP NOT NULL, enabled BOOLEAN DEFAULT TRUE, timestamp TIMESTAMP NOT NULL, entity_id VARCHAR(255), name VARCHAR(255) NOT NULL, scope INTEGER, value VARCHAR(65535) NOT NULL, tool BIGINT REFERENCES xhbm_tool, UNIQUE (tool, name, scope, entity_id));
