', 'emailMessageSystemPathError', 0, '<p>The following system path errors have been discovered:\n<br>ERRORS_LIST</p>', 5), (144, '2021-09-23 13:38:00.304', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.304', 'smtpPort', 0, '25', 5), (145, '2021-09-23 13:38:00.315', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.315', 'smtpHostname', 0, 'localhost', 5), (146, '2021-09-23 13:38:00.321', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.321', 'emailAllowNonuserSubscribers', 0, 'true', 5), (147, '2021-09-23 13:38:00.328', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.328', 'emailMessageProjectAccessDenial', 0, '<p>We regret to inform you that your request to access the PROJECT_NAME project has been denied.  Please consult the project manager for additional details at USER_EMAIL.</p>\n<p>The SITE_NAME team.<br>\nSITE_URL <br>\nADMIN_MAIL</p>', 5), (148, '2021-09-23 13:38:00.336', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.336', 'copyAdminOnPageEmails', 0, 'true', 5), (149, '2021-09-23 13:38:00.343', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.343', 'emailMessageUploadByReferenceSuccess', 0, '<p>The upload by reference requested by USER_USERNAME has finished successfully.\n<br>DUPLICATES_LIST</p>', 5), (150, '2021-09-23 13:38:00.348', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.348', 'notifyAdminPipelineEmails', 0, 'true', 5), (151, '2021-09-23 13:38:00.353', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.353', 'smtpStartTls', 0, 'false', 5), (152, '2021-09-23 13:38:00.358', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.358', 'emailMessagePipelineDefaultSuccess', 0, '<p>Dear USER_FIRSTNAME USER_LASTNAME,</p>\n <p>PIPELINE_NAME has completed without errors for EXPERIMENT_NAME.</p>\n <p>Details are available at SUCCESS_URL. <br>\nSITE_NAME team</p>', 5), (153, '2021-09-23 13:38:00.363', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.363', 'smtpSslTrust', 0, '', 5), (154, '2021-09-23 13:38:00.375', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.375', 'smtpPassword', 0, '', 5), (155, '2021-09-23 13:38:00.382', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.382', 'emailMessageAddressChanged', 0, '<p>Your email address was successfully changed to NEW_EMAIL.</p>', 5), (156, '2021-09-23 13:38:00.386', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.386', 'helpContactInfo', 0, '', 5), (157, '2021-09-23 13:38:00.39', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.39', 'emailMessageNewUserVerification', 0, '<p>USER_FIRSTNAME USER_LASTNAME, </p>\n<p>We received a request to register an account for you on XNAT. If you did not make this request, you can safely ignore this email. </p>\n<p>If you would like to register, please confirm your email address by clicking this link within the next 24 hours: VERIFY_URL </p>\n<p>After verifying your email address, you will be able to immediately log in and start using XNAT. </p>\n<p>To request a new email verification link, please click this link and select "Resend email verification": FORGOT_LOGIN_URL</p>', 5), (158, '2021-09-23 13:38:00.394', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.394', 'emailMessagePipelineAutorunSuccess', 0, '<p>Dear USER_FIRSTNAME USER_LASTNAME,</p>\n <p>The following session was archived in SITE_NAME <ul style="list-style-type:none;"> <li> Project: PROJECT_NAME</li> <li>Subject: SUBJECT_NAME</li> <li>Session: EXPERIMENT_NAME</li> </ul><p>Additional details for this session are available SUCCESS_URL.\n<br>SITE_NAME team</p>', 5), (159, '2021-09-23 13:38:00.397', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.397', 'emailMessageUserRegistration', 0, '<p>Dear USER_FIRSTNAME USER_LASTNAME,</p> <p>Welcome to the SITE_NAME Web Archive!</p> <p>You can now log on to the SITE_NAME at: SITE_URL</p><p>Your username is: USER_USERNAME</p> <p>For support, contact the ADMIN_EMAIL</p>', 5), (160, '2021-09-23 13:38:00.402', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.402', 'emailMessageNewUserNotification', 0, '<p>New User Created</p>\n<ul style="list-style-type:none;"> <li>Time: TIME</li> <li>Site: SITE_NAME</li> <li>Host: SITE_URL</li> <li>Username: USER_USERNAME</li> <li>First: USER_FIRSTNAME</li> <li>Last: USER_LASTNAME</li> <li>Phone: USER_PHONE</li> <li>Lab: LAB_NAME</li> <li>Email: USER_EMAIL</li> </ul><p>This account has been created and automatically enabled based on the current system configuration.</p>\n<p>The account has open project access requests for the following projects: PROJECT_ACCESS_REQUESTS</p>\n<p> REVIEW_LINK </p>\n<p>User Comments: USER_COMMENTS</p>', 5), (161, '2021-09-23 13:38:00.406', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.406', 'emailMessageProjectRequestAccess', 0, '<p>Hello,</p>\n<p>We received a request to access the PROJECT_NAME project from a user on SITE_NAME as a(n) RQ_ACCESS_LEVEL. Granting this kind of access in this project will mean the user can LIST_PERMISSIONS</p>\n<p>Login: USER_USERNAME<br>\nEmail: USER_EMAIL<br>\nFirstname: USER_FIRSTNAME<br>\nLastname: USER_LASTNAME<br>Comments: RQA_COMMENTS<br>\nTo approve or deny this project access request, please click the following link: ACCESS_URL</p>\n<p>The SITE_NAME team.<br>\nSITE_URL <br>\nADMIN_MAIL</p>', 5), (162, '2021-09-23 13:38:00.41', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.41', 'emailMessageUnauthorizedDataAttempt', 0, '<p>Unauthorized access TYPE USER_DETAILS prevented</p>', 5), (163, '2021-09-23 13:38:00.413', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.413', 'emailMessageInviteProjectAccess', 0, '<p>Hello,</p>\n<p>You have been invited to join the PROJECT_NAME project on SITE_NAME by USER_FIRSTNAME USER_LASTNAME. If you were not expecting to receive this invitation, you can safely ignore this email.\n</p><p>To accept this invitation and begin working in this project, please click the following link: ACCEPT_URL \n<br />\n<br /></p><p>The SITE_NAME team.\n<br />SITE_URL \n<br />ADMIN_MAIL</p>', 5), (164, '2021-09-23 13:38:00.417', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.417', 'emailMessageForgotPasswordReset', 0, '<p>Dear USER_FIRSTNAME USER_LASTNAME,</p>\n<p>Please click this link to reset your password: RESET_URL</p> \n<p>This link will expire in 24 hours.</p>', 5), (165, '2021-09-23 13:38:00.422', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.422', 'smtpUsername', 0, '', 5), (166, '2021-09-23 13:38:00.427', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.427', 'emailMessageDataAlertCustom', 0, '<p>Hello, </p> <p>USER_FIRSTNAME USER_LASTNAME thought you might be interested in a data set contained in the SITE_NAME. Please follow REQUEST_LINK to view the data.</p>\n<p>Message from sender:<br>\nSENDER_MESSAGE<br>\n</p> <p>This email was sent by the SITE_URL data management system on TIME_SENT. If you have questions or concerns, please contact HELP_CONTACT</p>.', 5), (167, '2021-09-23 13:38:00.434', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.434', 'notifyAdminSessionTransfer', 0, 'true', 5), (168, '2021-09-23 13:38:00.438', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.438', 'emailMessageNewUserRequest', 0, '<p>New User Request</p>\n<ul style="list-style-type:none;"> <li> Time: TIME</li> <li>Site: SITE_NAME</li> <li>Host: SITE_URL<</li> <li>Username: USER_USERNAME</li> <li>First: USER_FIRSTNAME</li> <li>Last: USER_LASTNAME</li> <li>Phone: USER_PHONE</li> <li>Lab: LAB_NAME</li> <li>Email: USER_EMAIL</li> </ul><p>This account has been created but will be disabled until you enable the account. You must log in before enabling the account.</p>\n<p>The account has open project access requests for the following projects: PROJECT_ACCESS_REQUESTS</p>\n<p> REVIEW_LINK </p>\n<p>User Comments: USER_COMMENTS</p>', 5), (169, '2021-09-23 13:38:00.442', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.442', 'notifyAdminUserRegistration', 0, 'false', 5), (170, '2021-09-23 13:38:00.446', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.446', 'emailMessageErrorMessage', 0, '<p>Error Thrown:</p>\n <ul style="list-style-type:none;"> <li>Host: SITE_URL</li> <li>User: USER_LOGIN (USER_USERNAME USER_LASTNAME)</li> <li>Time: ERROR_TIME</li> <li>Error: ERROR_MESSAGE</li> </ul>', 5), (171, '2021-09-23 13:38:00.451', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.451', 'emailPrefix', 0, 'XNAT', 5), (172, '2021-09-23 13:38:00.455', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.455', 'emailMessageBatchWorkflowComplete', 0, '<p>Dear USER_FIRSTNAME USER_LASTNAME,</p>\n <p>The following batch procedure has been completed: \n<br>PROCESS_NAME </p>\n<p>NUMBER_MESSAGES successful transfer(s).\n<br>MESSAGES_LIST \n<br>ERRORS_LIST \n<br>Details for this project are available at SITE_URL.</p>\n<p>The SITE_NAME team.<br>\nSITE_URL <br>\n ADMIN_MAIL </p>', 5), (173, '2021-09-23 13:38:00.459', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.459', 'notifyAdminProjectAccessRequest', 0, 'true', 5), (174, '2021-09-23 13:38:00.464', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.464', 'copyAdminOnNotifications', 0, 'true', 5), (175, '2021-09-23 13:38:00.473', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.473', 'smtpAuth', 0, 'false', 5), (176, '2021-09-23 13:38:00.478', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.478', 'emailMessagePipelineDefaultFailure', 0, '<p>The pipeline PIPELINE_NAME encountered an error.</p> <ul style="list-style-type:none;"> <li>Project: PROJECT_NAME</li> <li>Experiment: EXPERIMENT_NAME</li> <li>Pipeline Step: PIPELINE_STEP </li> </ul><p>The SITE_NAME technical team is aware of the issue and will notify you when it has been resolved.</p>\n <p>We appreciate your patience. Please contact CONTACT_EMAIL with questions or concerns.</p>\n +<p>ATTACHMENTS_STATEMENT<br>\nSTDOUT<br>\nSTDERR</p>', 5), (177, '2021-09-23 13:38:00.482', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.482', 'emailMessageProjectAccessApproval', 0, '<p>Hello,</p>\n<p>You have been granted access to the PROJECT_NAME project as a member of the RQ_ACCESS_LEVEL group.</p>\n<p>To proceed to SITE_URL and begin working with this project, please click the following link: ACCESS_URL</p>\n<p>The SITE_NAME team.<br>\nSITE_URL <br>\nADMIN_MAIL </p>', 5), (178, '2021-09-23 13:38:00.487', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.487', 'emailMessageVerifyEmailChangeRequest', 0, '<p>A request was made to change the email address for the user with username USER_USERNAME to this address. If you did not make this request, you can ignore this email. If you made this request and wish to have this change take effect, please log into your account and click CHANGE_EMAIL_LINK.</p>', 5), (179, '2021-09-23 13:38:00.498', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.498', 'emailMessageForgotUsernameRequest', 0, '<p>You requested your username, which is: USER_USERNAME</p>\n <p>Please login to the site for additional user information SITE_URL.</p>\n', 5), (180, '2021-09-23 13:38:00.502', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.502', 'emailMessageUploadByReferenceFailure', 0, '<p>The upload by reference requested by USER_USERNAME has encountered an error.</p>\n <p>Please contact your IT staff or the application logs for more information.</p>', 5), (181, '2021-09-23 13:38:00.511', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:00.511', 'emailMessageDisabledUserVerification', 0, '<p>Expired User Reverified</p>\n<ul style="list-style-type:none;"> <li>Date: DATE_INPUT</li> <li>Site: SITE_NAME</li> <li>Host: SITE_URL</li> <li>Username: USER_USERNAME</li> <li>First: USER_FIRSTNAME</li> <li>Last: USER_LASTNAME</li></ul><p>After being disabled due to inactivity, the owner of this account has completed the email verification process to show that they are still the proper account owner. This user account is now no longer disabled due to inactivity and they can access the site again.\n</p><p> The LOGIN_URL verified user account USER_LOGIN has been enabled.</p>', 5), (182, '2021-09-23 13:38:04.671', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:04.671', 'dicomSCPInstances:1', 0, '{"port":8104,"id":1,"aeTitle":"XNAT"}', 6), (183, '2021-09-23 13:38:05.716', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:05.716', 'purgeAndRefreshOnStartup', 0, 'true', 7), (184, '2021-09-23 13:38:05.893', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:05.893', 'allowAutoRunProjectOverride', 0, 'false', 8), (185, '2021-09-23 13:38:05.908', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:05.908', 'autoRunEnabled', 0, 'false', 8), (186, '2021-09-23 13:38:06.104', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:06.104', 'internalScriptingEnabled', 0, 'true', 9), (187, '2021-09-23 13:38:06.139', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:06.139', 'fileStorePath', 0, '${FOLDER}/fileStore', 10), (188, '2021-09-23 13:38:07.187', '1969-12-31 18:00:00', 't', '2021-09-23 13:38:07.187', 'enabled', 0, 'false', 11), (54, '2021-09-23 13:37:55.38', '1969-12-31 18:00:00', 't', '2021-09-23 13:41:28.678', 'sitewideAnonymizationScript', 0, '//\n// Default XNAT anonymization script\n// XNAT http://www.xnat.org\n// Copyright (c) 2005-2017, Washington University School of Medicine and Howard Hughes Medical Institute\n// All Rights Reserved\n//\n// Released under the Simplified BSD.\n//\nversion "6.1"\nproject != "Unassigned" ? (0008,1030) := project\n(0010,0010) := subject\n(0010,0020) := session', 2);
